<template><div class="grid"><div class="glass panel"><div class="panel-top"><h3>{{item.id?'Writing tahrirlash':'Yangi writing set'}}</h3><button v-if="item.id" class="link-btn" @click="reset">Bekor qilish</button></div><p class="help">Har qatorda: <code>Uzbek gap | accepted English | boshqa variant</code>.</p><form @submit.prevent="$emit('save',{...item})"><div class="row"><label>Level<select v-model.number="item.level"><option v-for="n in 15" :key="n" :value="n">Level {{n}}</option></select></label><label>Sarlavha<input v-model.trim="item.title" required placeholder="Daily routine" /></label></div><label>Prompts<textarea v-model="item.promptsRaw" rows="12" placeholder="Men har kuni o‘qiyman. | I study every day | I learn every day" required></textarea></label><button class="primary" :disabled="saving">{{saving?'Saqlanmoqda…':item.id?'Saqlash':'Writing qo‘shish'}}</button></form></div><div class="glass panel"><div class="panel-top"><h3>Custom writing <span>{{items.length}}</span></h3></div><div v-if="!items.length" class="empty">Hali custom writing yo‘q.</div><div v-for="x in items" :key="x.id" class="item"><div><b>{{x.writing.title}}</b><span>Level {{x.writing.level}}</span><small>{{x.writing.prompts?.length||0}} prompt</small></div><div class="actions"><button @click="$emit('edit',x)"><i class="ti ti-pencil"></i></button><button class="danger" @click="$emit('delete',x.id)"><i class="ti ti-trash"></i></button></div></div></div></div></template>
<script setup>import {ref,watch} from 'vue';const props=defineProps({items:Array,initial:Object,saving:Boolean});const emit=defineEmits(['save','edit','delete']);const item=ref({...props.initial});watch(()=>props.initial,v=>item.value={...v},{deep:true});function reset(){item.value={level:1,title:'',promptsRaw:''}}</script><style scoped>@import './editor.css';</style>
